"""Operations on tags: what each one checks before it writes."""

from collections.abc import Mapping
from typing import Any

from app.entities.tag import Tag
from app.errors import FieldError, NotFoundError, ValidationFailedError
from app.paging import Page
from app.unit_of_work import UnitOfWork

# Columns a client may send: the database fills the others
_FIELDS = frozenset({"label"})


class TagService:
    """Operations on tags. Repositories commit every write."""

    def __init__(self, uow: UnitOfWork) -> None:
        self._uow = uow

    def _validate_all(self, values: dict[str, Any], current: Tag | None) -> None:
        """Checks the values against the rules of the "tags" table; raises ValidationFailedError with every problem."""
        creating = current is None
        errors: list[FieldError] = []
        for name in values.keys() - _FIELDS:
            errors.append(FieldError(name, "is not a field of Tag"))
        if not creating:
            for name in values.keys() & {"id"}:
                errors.append(FieldError(name, "cannot be changed"))
        value = values.get("label")
        if value is None:
            if creating or "label" in values:
                errors.append(FieldError("label", "is required"))
        else:
            if isinstance(value, str) and len(value) > 30:
                errors.append(FieldError("label", "is longer than 30 characters"))
        if errors:
            raise ValidationFailedError("Tag", errors)

    def _check(self, values: dict[str, Any], current: Tag | None) -> None:
        """Every check before a write: the values, the rows they point to, the unique values."""
        self._validate_all(values, current)

    def _find(self, id: int) -> Tag:
        """The Tag with this key; NotFoundError when there is none."""
        entity = self._uow.tags.find_by_id(id)
        if entity is None:
            raise NotFoundError("Tag", id)
        return entity

    def create_tag(self, tag: Tag) -> Tag:
        """Stores a new Tag after checking it."""
        values = {name: getattr(tag, name) for name in _FIELDS}
        self._check(values, None)
        created = self._uow.tags.insert(tag)
        return created

    def get_tag(self, id: int) -> Tag:
        """The Tag with this key; NotFoundError when there is none."""
        return self._find(id)

    def list_tags(self, offset: int = 0, limit: int = 50) -> Page[Tag]:
        """A page of tags, by primary key."""
        return self._uow.tags.list(offset, limit)

    def update_tag(self, id: int, changes: Mapping[str, Any]) -> Tag:
        """Changes the given values of a Tag."""
        values = dict(changes)
        current = self._find(id)
        self._check(values, current)
        for name, value in values.items():
            setattr(current, name, value)
        updated = self._uow.tags.update(current)
        return updated

    def delete_tag(self, id: int) -> None:
        """Deletes a Tag."""
        current = self._find(id)
        self._uow.tags.delete(current)

